// Why Code: parsing reply bodies and matching sender -> pending assignment needs regex + sorting.
const inbox = $input.all();
const cfgRows = $('Read Settings').all().map((i) => i.json);
const cfg = {};
for (const r of cfgRows) { const k = String(r.key ?? '').trim(); if (k) cfg[k] = r.value ?? ''; }
const rows = $('Read Rota').all().map((i) => i.json);
const tz = 'Africa/Lagos';
const now = DateTime.now().setZone(tz);
const emailRe = /[\w.+-]+@[\w-]+\.[\w.]+/;
const out = [];
for (const it of inbox) {
  const j = it.json;
  const subject = String(j.subject || '');
  const body = String(j.textPlain || j.textHtml || j.text || j.snippet || '');
  if (!/^(yes|y|confirm|ok|confirmed)\b/i.test((subject + ' ' + body).trim())) continue;
  const fromRaw = String((j.from && j.from.value && j.from.value[0] && j.from.value[0].address) || j.from || '');
  const m = fromRaw.match(emailRe);
  if (!m) continue;
  const fromAddr = m[0].toLowerCase();
  const pending = rows
    .filter((r) => String(r.email).toLowerCase() === fromAddr && String(r.status).toUpperCase() === 'PENDING')
    .map((r) => ({ ...r, start: DateTime.fromFormat(String(r.date) + ' ' + String(r.startTime), 'yyyy-MM-dd HH:mm', { zone: tz }) }))
    .filter((r) => r.start.isValid && r.start.diff(now, 'hours').hours > -12)
    .sort((a, b) => a.start - b.start);
  const r = pending[0];
  if (!r) continue;
  out.push({ json: {
    assignmentId: r.assignmentId, toEmail: fromAddr, fromEmail: cfg.fromEmail || '',
    replySubject: 'Re: ShiftHub - shift confirmed',
    replyText: 'Confirmed: ' + r.ward + ' | ' + r.date + ' ' + r.startTime + '-' + r.endTime + '. Thank you! See you at your shift.',
  } });
}
return out;
